frappe.web_form.after_load = function() {
    console.log("Web Form loaded!");

    function getWeekDateRange(year, weekNumber) {
        const jan1 = new Date(year, 0, 1);
        const jan1Day = jan1.getDay() || 7; // treat Sunday as 7
        const firstMonday = new Date(jan1);
        firstMonday.setDate(jan1.getDate() + (1 - jan1Day) + (jan1Day > 1 ? 7 : 0));
        const dateFrom = new Date(firstMonday);
        dateFrom.setDate(firstMonday.getDate() + (weekNumber - 1) * 7);
        const dateUntil = new Date(dateFrom);
        dateUntil.setDate(dateFrom.getDate() + 4);
        return { dateFrom, dateUntil };
    }

    // URL parameters
    const params = new URLSearchParams(window.location.search);
    const week_number = params.get("week_number");
    const customer_param = params.get("customer");

    // Prefill fields
    const prefill_fields = [
        "week_number",
        "customer",
        "contact",
        "address",
        "default_order_type",
        "default_addon_telur",
        "default_addon_buah",
        "default_addon_juice",
        "default_addon_extra_size"
    ];

    prefill_fields.forEach((fieldname) => {
        const value = params.get(fieldname);
        if (value) {
            frappe.web_form.set_value(fieldname, value);
            console.log(`Prefilled ${fieldname}:`, value);
        }
    });

    // Calculate week dates
    if (week_number) {
        const currentYear = new Date().getFullYear();
        const { dateFrom, dateUntil } = getWeekDateRange(currentYear, parseInt(week_number, 10));
        const formatDate = (d) => d.toISOString().split("T")[0];

        frappe.web_form.set_value("date_from", formatDate(dateFrom));
        frappe.web_form.set_value("date_until", formatDate(dateUntil));

        console.log("Week date range:", formatDate(dateFrom), "to", formatDate(dateUntil));
    }

    // Fetch customer info from API
        if (customer_param) {
        frappe.call({
            method: "catering_management.api.get_customer_info",
            args: { customer_name: customer_param },
            callback: function(res){
                if(res.message){
                    // Prefill only customer_name and phone_number
                    if (res.message.customer_name) {
                        frappe.web_form.set_value("customer_name", res.message.customer_name);
                        console.log("Customer Name:", res.message.customer_name);
                    }
                    if (res.message.phone_number) {
                        frappe.web_form.set_value("phone_number", res.message.phone_number);
                        console.log("Phone Number:", res.message.phone_number);
                    }
                    if (res.message.complete_address) {
                        frappe.web_form.set_value("complete_address", res.message.complete_address);
                        console.log("Complete Address:", res.message.complete_address);
                    }
                }
            },
            error: function(err){
                console.error("API call error:", err);
            }
        });
    }
};
